<template><div class="checkout-wrap"><button class="text-button" @click="$router.push({path:'/guest',query:{storeId}})">← 返回菜单</button><h1>确认订单</h1><el-alert v-if="!storeOpen" title="店铺暂时停止接单，请稍后再来。" type="warning" :closable="false"/><label class="table-field">桌号 <el-input v-model="tableNo" placeholder="例如 A12" maxlength="20" /></label><div v-for="item in items" :key="item.productId" class="checkout-item"><span>{{item.name}} × {{item.quantity}}</span><b>¥{{item.subtotal.toLocaleString()}}</b></div><div class="checkout-total"><span>合计</span><b>¥{{total.toLocaleString()}}</b></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-if="order" class="success-card"><div>✓</div><h2>订单已提交</h2><p>订单编号：{{order.id}}</p><el-button type="primary" @click="$router.push({path:'/guest/history',query:{storeId}})">查看订单历史</el-button></div><div v-else class="checkout-actions"><el-button @click="$router.push({path:'/guest',query:{storeId}})">返回修改</el-button><el-button type="primary" :loading="sending" :disabled="!storeOpen" @click="submit">提交订单</el-button></div></div></template>
<script setup lang="ts">import {computed,ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {api,type Product,type Order} from '../api';import {cart} from '../cart';import {activeStoreId} from '../storeContext';const route=useRoute(),storeId=String(route.query.storeId||activeStoreId.value),tableNo=ref(''),products=ref<Product[]>([]),storeOpen=ref(true),error=ref(''),sending=ref(false),order=ref<Order|null>(null);onMounted(async()=>{try{const [p,s]=await Promise.all([api.get('/products',{params:{storeId}}),api.get('/store',{params:{storeId}})]);products.value=p.data.data;storeOpen.value=s.data.data.isOpen}catch(e:any){error.value=e.message}});const items=computed(()=>products.value.filter(p=>cart[p.id]).map(p=>({productId:p.id,name:p.name,price:p.price,quantity:cart[p.id],subtotal:p.price*cart[p.id]}))),total=computed(()=>items.value.reduce((n,i)=>n+i.subtotal,0));async function submit(){error.value='';if(!tableNo.value.trim()){error.value='请填写桌号';return}if(!items.value.length){error.value='请至少选择一个商品';return}if(!storeOpen.value){error.value='店铺暂时停止接单';return}sending.value=true;try{const submitted=(await api.post('/orders',{storeId,tableNo:tableNo.value,items:items.value,total:total.value})).data.data as Order&{receiptToken:string};order.value=submitted;const key=`guest-orders:${storeId}`,entries=JSON.parse(localStorage.getItem(key)||'[]') as Array<{id:string;token:string}>;localStorage.setItem(key,JSON.stringify([{id:submitted.id,token:submitted.receiptToken},...entries.filter(row=>row.id!==submitted.id)]));Object.keys(cart).forEach(k=>delete cart[Number(k)])}catch(e:any){error.value=e.message}finally{sending.value=false}}</script>
